{
  "location": "global",
  "properties": {
    "description": "Alert when error budget is consumed too fast",
    "severity": 2,
    "windowSize": "PT5M",
    "evaluationFrequency": "PT1M",
    "criteria": {
      "allOf": [
        {
          "name": "HighErrorRate",
          "metricTrigger": {
            "metricName": "availabilityResults/availabilityPercentage",
            "metricNamespace": "microsoft.insights/components",
            "threshold": 99.5,
            "operator": "LessThan",
            "timeAggregation": "Average"
          }
        }
      ]
    }
  }
}
